from datetime import date, timedelta
from typing import Dict

class Loyalty:
    def __init__(self) -> None:
        self.customers: Dict[str, Dict[date, int]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")

        points = int(amount // 10)
        if customer not in self.customers:
            self.customers[customer] = {}

        # Points become available 14 days after the purchase
        available_day = day + timedelta(days=14)
        if available_day not in self.customers[customer]:
            self.customers[customer][available_day] = 0
        self.customers[customer][available_day] += points

        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        if customer not in self.customers:
            return 0

        balance = 0
        for available_day, points in self.customers[customer].items():
            if available_day <= day:
                balance += points

        return balance

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points."""
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100")

        if customer not in self.customers:
            raise ValueError("Customer has no points to redeem")

        available_points = self.balance(customer, day)
        if available_points < points:
            raise ValueError("Insufficient points to redeem")

        # Remove points from the earliest available dates first
        points_to_remove = points
        for available_day in sorted(self.customers[customer].keys()):
            if available_day <= day:
                if self.customers[customer][available_day] <= points_to_remove:
                    points_to_remove -= self.customers[customer][available_day]
                    del self.customers[customer][available_day]
                else:
                    self.customers[customer][available_day] -= points_to_remove
                    break
            else:
                break

# Example usage
if __name__ == "__main__":
    loyalty = Loyalty()
    print(loyalty.purchase("John", 100.0, date(2024, 1, 1)))  # 10 points
    print(loyalty.balance("John", date(2024, 1, 1)))  # 0 points
    print(loyalty.balance("John", date(2024, 1, 15)))  # 10 points
    loyalty.redeem("John", 100, date(2024, 1, 15))  # Redeem 10 points
    print(loyalty.balance("John", date(2024, 1, 15)))  # 0 points
